SELECT CASE WHEN CAST(:week AS INTEGER) = 1 THEN date(substr(at, 1, 10), '-6 days', 'weekday 1') ELSE substr(at, 1, 10) END AS period, learner AS learner, COUNT(*) AS n, CAST(COALESCE(SUM(correct), 0) AS INTEGER) AS "right" FROM progress_answer WHERE subject_id = CAST(:subject_id AS INTEGER) AND substr(at, 1, 10) >= :since AND (:student = '' OR learner = :student) GROUP BY period, learner ORDER BY period ASC, learner ASC
